         const rib=Math.sin(x/width*Math.PI*7+.3)*.055,spec=Math.exp(-((x/width-.36)**2/.008+(y/height-.27)**2/.06))*.22;
         for(let c=0;c<3;c++)data[k+c]=data[k+c]*(1+rib)+(255-data[k+c])*spec;
